import{newSpecPage}from"@stencil/core/testing";import{ScPriceChoice}from"../sc-price-choice";jest.mock("../../../../../services/fetch",(()=>({getPricesAndProducts:jest.fn().mockResolvedValue({prices:{},products:{}})}))),describe("sc-price-choice",(()=>{it("renders",(async()=>{const e=await newSpecPage({components:[ScPriceChoice],html:"<sc-price-choice></sc-price-choice>"});expect(e.root).toMatchSnapshot()})),it("renders a price whose product was collapsed to an id (draft product)",(async()=>{const e=await newSpecPage({components:[ScPriceChoice],html:"<sc-price-choice></sc-price-choice>"});e.root.priceId="price_1",await e.waitForChanges(),e.root.products={},e.root.prices={price_1:{id:"price_1",name:"One-time",archived:!1,product:"prod_draft"}},await e.waitForChanges(),expect(e.root.querySelector("sc-choice-container")).not.toBeNull(),expect(e.root.querySelector("sc-alert")).toBeNull()})),it("hides a price whose product is archived",(async()=>{const e=await newSpecPage({components:[ScPriceChoice],html:"<sc-price-choice></sc-price-choice>"});e.root.priceId="price_1",await e.waitForChanges(),e.root.products={prod_1:{id:"prod_1",archived:!0}},e.root.prices={price_1:{id:"price_1",name:"One-time",archived:!1,product:"prod_1"}},await e.waitForChanges(),expect(e.root.querySelector("sc-choice-container")).toBeNull()}))}));